  stages[2]={name:stages[2].name,confirmed:true,status:"CONFIRMED",detail:dir+" MSS candle close "+sigFmt(ms.close)+" broke post-sweep structure",time:timeTxt(ms),price:ms.close,timeframe:"30m"};
