  const pools=setup.dir==="BUY"?[...highs,weeklyHigh,dailyHigh].filter(x=>x&&x>entryPrice).sort((a,b)=>a-b):[...lows,weeklyLow,dailyLow].filter(x=>x&&x<entryPrice).sort((a,b)=>b-a);
